import{_ as o,o as e,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Gemini 首帧与首尾帧锁定","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-first-last-frame.md","filePath":"tools/gemini-first-last-frame.md","lastUpdated":1786871523000}'),s={name:"tools/gemini-first-last-frame.md"};function r(l,t,n,d,c,h){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="gemini-首帧与首尾帧锁定" tabindex="-1">Gemini 首帧与首尾帧锁定 <a class="header-anchor" href="#gemini-首帧与首尾帧锁定" aria-label="Permalink to &quot;Gemini 首帧与首尾帧锁定&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及 Veo 的 Image-to-Video 能力与「废片率」为经验估算，请以官方文档为准。</li></ul></div><blockquote><p>提问：</p><ol><li>首帧锁定 vs 只给文字 prompt，稳定性和一致性到底差多少，值不值得每次都出首帧？</li><li>首尾帧（First &amp; Last Frame）具体怎么用？给了起始图和落点图后，中间运动容易乱抖、发糊，怎么约束？</li></ol></blockquote><h2 id="核心结论" tabindex="-1">核心结论 <a class="header-anchor" href="#核心结论" aria-label="Permalink to &quot;核心结论&quot;">​</a></h2><p>首帧锁定（Image-to-Video, I2V）与纯文字（Text-to-Video, T2V）存在<strong>代际差异</strong>。在食品广告里，<strong>极度值得每次都出首帧——它是商业级交片的「生命线」</strong>。</p><table tabindex="0"><thead><tr><th>维度</th><th>纯文字（T2V）</th><th>首帧锁定（I2V）</th></tr></thead><tbody><tr><td>主体一致性</td><td>低/不可控，每次薯条长短粗细截面都变</td><td>极高，直接继承参考图材质/造型/配色</td></tr><tr><td>材质质感</td><td>凭空随机，蜂蜜黏稠度、番茄挂壁感易飘忽</td><td>精准锁定高光/透光/纹理，AI 只做动力学</td></tr><tr><td>构图运镜</td><td>模糊理解，视角摆盘随机</td><td>完全掌控，首帧定死黄金构图与焦点</td></tr><tr><td>废片率</td><td>抽卡 70%–90%</td><td>可降到 20%–30%</td></tr></tbody></table><p><strong>推荐标准工业流程</strong>：文生图（定风格/首帧）→ PS 修瑕疵 → 图生视频（只写运动/运镜/物理现象）。</p><h2 id="首尾帧的三种典型用法" tabindex="-1">首尾帧的三种典型用法 <a class="header-anchor" href="#首尾帧的三种典型用法" aria-label="Permalink to &quot;首尾帧的三种典型用法&quot;">​</a></h2><p>首尾帧的作用是<strong>设定起点与终点，让 AI 填充中间的物理运动</strong>。</p><ol><li><strong>材质形态变幻</strong>：首帧 = 整颗黄油切块/新鲜番茄，尾帧 = 金黄酥脆裹粉薯条；中间由 AI 补全「融化裹住 / 爆破成粉」。</li><li><strong>运镜空间推拉</strong>：首帧 = 微距颗粒特写，尾帧 = 包装袋中景 + Logo；AI 补全「镜头拉远，颗粒随镜头后退」。</li><li><strong>动态交互</strong>：首帧 = 手指捏起薯条，尾帧 = 蘸酱拉丝；AI 补全自然蘸酱动作。</li></ol><h2 id="为什么「乱抖、发糊」" tabindex="-1">为什么「乱抖、发糊」 <a class="header-anchor" href="#为什么「乱抖、发糊」" aria-label="Permalink to &quot;为什么「乱抖、发糊」&quot;">​</a></h2><ul><li><strong>首尾帧逻辑不一致</strong>：两张图的光影、角度、主体比例、背景结构差异过大，AI 找不到物理轨迹，图像撕裂/重合。</li><li><strong>缺运动提示</strong>：没告诉 AI 中间发生什么，它随机扩散导致画质下降。</li><li><strong>相机运镜剧烈</strong>：主体在动、镜头也在转，运动矢量叠加过载。</li></ul><h2 id="_5-个约束技巧" tabindex="-1">5 个约束技巧 <a class="header-anchor" href="#_5-个约束技巧" aria-label="Permalink to &quot;5 个约束技巧&quot;">​</a></h2><ol><li><strong>控制首尾帧连贯性（图像侧）</strong>：首尾帧的主体比例、镜头角度、光源方向、色调必须一致。建议用 PS / 图生图在「同一底图空间」内加工首尾帧。</li><li><strong>单轴 / 单向运动动词（文本侧）</strong>：一次只给 1–2 个方向明确的矢量运动，别写 <code>spinning, bursting, shaking, zoom in and flying</code> 组合。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Smooth high-speed macro shot. Liquid honey drips down vertically onto the golden potato fries. The camera slowly pushes in. Cinema-grade lighting, crisp focus, hyper-realistic, 8k, no jitter.</span></span></code></pre></div><ol start="3"><li><strong>加专业广告锚点词</strong>：<code>Slow motion</code>、<code>High-speed camera 1000fps</code>、<code>Locked camera</code>、<code>Smooth linear push-in</code>；防糊词 <code>Crisp details</code>、<code>Sharp focus throughout</code>、<code>No motion blur</code>。</li><li><strong>分步渲染</strong>：动作太复杂（切片爆破→变汁→包裹）别一镜到底，拆成 2–3 段 2 秒短镜头，硬切/Wipe 衔接，远比单段稳定。</li><li><strong>后期兜底</strong>：Topaz Video AI 补帧到 60/120fps 降抖动；把变糊的 1–2 帧导出贴清晰纹理再合成。</li></ol><hr><p>关联：用哪张图做首帧最稳见 <a href="/tools/gemini-reference-image">参考图去风格</a>；跨 8 镜头的一致性工作流见 <a href="/tools/gemini-shot-consistency">跨镜头一致性</a>；防抖的运镜词见 <a href="/tools/gemini-camera-failsafe">运镜翻车词</a>。</p>',18)])])}const p=o(s,[["render",r]]);export{m as __pageData,p as default};
